以下完整程序输出什么？
```go
package main
import "fmt"
func counter() func() int {
    n := 0
    return func() int { n++; return n }
}
func main() {
    next := counter()
    fmt.Println(next(), next())
}
```

以下完整程序输出什么？
```go
package main
import "fmt"
type Counter struct { N int }
func (c *Counter) Inc() { c.N++ }
func main() {
    c := Counter{}
    c.Inc()
    fmt.Println(c.N)
}
```

